export default pattern<IframeTeamPollInput, IframeTeamPollOutput>(({
  input,
  output,
}) => {
  const state = new Writable<IframeStateData>(DEFAULT_STATE);
  const context = IframeContext({
    input,
    state,
    output,
  });

  return {
    [NAME]: "Iframe · Team poll",
    [UI]: (
      <div style={{ width: "100%", height: "680px" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
